"""RingaRoofer library upgrade (Nov 2026): category pages (chain level 2), per-problem 'what a roofer does' + 'what to tell the roofer' + more FAQs,
and the roof dictionary. Wording follows build.py BANNED (no damage, gutter, window, siding, chimney, skylight, fascia, soffit, solar, claim,
professional, cost, price, rate, quote, deal, save, free, low/lower, best, estimate, insurance, licensed, certified, guarantee, warranty...)."""

# ---------------------------------------------------------------- categories
CAT = {
 "leaks": dict(photo="ceiling", short="Drips, ceiling stains, leaks in heavy rain, around vents, or after a new roof.",
  h1="Roof leaks and ceiling stains: find the cause, know what to do",
  lead="Water shows up inside far from where it gets in. Here's how roof leaks travel, what you can check from inside and from the ground, and what a roofer looks for.",
  how=["A roof is layers: <b>shingles</b> or panels on top, <b>underlayment</b> under them, and the wood <b>roof deck</b> under that. Water that gets past the top layer runs along the underlayment or the deck before it drips.",
       "Most leaks start where the roof is interrupted: <b>pipe boots</b> around plumbing vents, <b>flashing</b> where the roof meets a wall, <b>valleys</b> where two slopes meet, and the <b>ridge</b> at the top.",
       "That's why a stain in one room can come from several feet uphill. Roofers trace it from the attic first, then check the roof above."],
  faq=[("Why does my roof only leak sometimes?", "Some leaks only show in wind-driven rain, heavy downpours or melting snow, when water reaches a weak spot from a certain direction."),
       ("Can a roof leak be far from the stain?", "Yes. Water runs along the underlayment and framing before it drips, so the entry point is often uphill from the stain."),
       ("Is a ceiling stain always the roof?", "No. Bathrooms, air conditioning lines and plumbing above can stain ceilings too. If it grows when it rains, think roof."),
       ("What's the most common roof leak spot?", "Around roof penetrations like plumbing vent pipes, and at flashing where the roof meets a wall."),
       ("Should I go on the roof to look?", "No. Wet or steep roofs are dangerous. Check from the attic and from the ground, and let a roofer go up."),
       ("Can a small leak wait?", "A small leak usually grows and can soak insulation and wood. Book a roofer soon, sooner if it's dripping.")]),
 "storm": dict(photo="storm2", short="Wind-blown shingles, hail, fallen trees and emergency tarps.",
  h1="Storm, wind and hail: what to check after the weather passes",
  lead="After a storm, check from the ground, take photos, cover what's open, and be careful who you hire. Here's the order to do it in.",
  how=["Wind lifts shingle edges first, usually at the <b>edges</b>, <b>corners</b> and <b>ridge</b> where wind pressure is strongest. FEMA's wind guidance explains why these areas take the most force.",
       "Hail can bruise shingles and knock off their protective <b>granules</b>, dent metal roofs and vents, and crack tiles. Some marks are only visible up close.",
       "After big storms, the FTC warns that door-to-door contractors often show up. Take your time, get everything in writing, and don't pay in full up front."],
  faq=[("What should I do right after a storm?", "Check from the ground, take photos of the roof and anything inside, cover leaks with buckets and towels, and call a roofer to check or tarp."),
       ("How do I know if hail hit my roof?", "Look for dents on vents, metal and outdoor equipment, piles of granules at downspouts, and dark spots on shingles. A roofer can check up close."),
       ("Is a tarp a real fix?", "No. A tarp keeps water out until a proper repair. Have it put on by someone who can do it safely."),
       ("Someone knocked on my door after the storm. Should I hire them?", "The FTC warns about door-to-door offers after weather events. Check them out, get the agreement in writing, and don't pay everything up front."),
       ("Do I need to fix wind-lifted shingles right away?", "Lifted or missing shingles leave the roof open to the next rain, so sooner is better."),
       ("Can wind blow off a whole section?", "Yes, especially at edges and corners. Keep people away from loose material and call a roofer.")]),
 "wear": dict(photo="oldroof", short="Granules in the downspouts, curling shingles, moss and nail pops.",
  h1="Wear and aging: signs your roof is getting older",
  lead="Roofs wear slowly: grit washes off, shingles curl, moss creeps in, nails back out. Here's how to read the signs and plan ahead instead of waiting for a leak.",
  how=["Asphalt shingles have a coating of <b>granules</b> that protect them from the sun. As they age, granules wash off and collect in downspouts.",
       "Heat and sun make shingles <b>curl</b>, <b>cup</b> or <b>crack</b>, usually first on the sunniest slopes. Poor attic airflow can speed this up.",
       "<b>Moss</b> holds moisture against the roof in shady, damp spots, and <b>nail pops</b> happen as wood moves with the seasons."],
  faq=[("Is it normal to see granules in my downspouts?", "Some after a new roof is normal. Lots of grit on an older roof is a sign of wear."),
       ("Why are my shingles curling?", "Age, heat and sun, and sometimes poor attic airflow."),
       ("Is moss bad for a roof?", "It holds moisture and can lift shingle edges over time. Have it removed gently."),
       ("What is a nail pop?", "A roofing nail that has backed up and lifted the shingle above it, which can let water in."),
       ("Does an older roof need replacing right away?", "Not necessarily. A roofer can tell you whether repairs make sense for a few more years."),
       ("How can I make my roof last longer?", "Good attic airflow, keeping debris off, trimming branches, and checking it after big storms.")]),
 "winter": dict(photo="house", short="Ice dams, damp attics and sagging roof lines.",
  h1="Winter and attic problems: ice dams, damp attics and sagging",
  lead="A lot of roof trouble starts in the attic. Warm air, trapped moisture and snow loads cause ice dams, damp insulation and sagging. Here's how it fits together.",
  how=["An <b>ice dam</b> forms when heat from the house melts snow on the upper roof, and the water refreezes at the colder edge. The Department of Energy's Building America guidance points to air sealing, insulation and ventilation as the fix.",
       "Attics need <b>airflow</b>: air in at the bottom edge of the roof, out near the top. ENERGY STAR explains that ventilation helps remove moisture and heat.",
       "A <b>sagging</b> roof line can mean wet or weakened decking, overloaded framing, or too many layers of roofing. It needs a roofer's look soon."],
  faq=[("Why do I get ice dams?", "Heat escaping into the attic melts snow higher up, and it refreezes at the colder roof edge."),
       ("How do I stop ice dams?", "Air sealing and insulating the attic floor and good ventilation, per DOE's Building America guidance. A roofer can also add an ice barrier along the edges."),
       ("Is frost in the attic normal?", "A little on very cold days can happen, but lots of frost or wet insulation means moisture is getting up there."),
       ("Is a sagging roof dangerous?", "It can be. Keep people out of rooms below a sagging ceiling and call a roofer soon."),
       ("Should I chip ice off the roof?", "No. You can break shingles and fall. Roof rakes from the ground can remove snow near the edge safely."),
       ("Can bathroom fans cause attic moisture?", "Yes, if they vent into the attic instead of outside.")]),
 "types": dict(photo="metal", short="Metal roof leaks, cracked tiles and ponding on flat roofs.",
  h1="Metal, tile and flat roofs: their own problems and checks",
  lead="Not every roof is shingles. Metal, tile and flat roofs each fail in their own ways. Here's what to look for on each.",
  how=["<b>Metal roofs</b> are panels held by screws or hidden clips. Many leaks come from screws whose rubber washers have aged, or from seams and flashing.",
       "<b>Tile roofs</b> (clay or concrete) shed water from the tiles, but the <b>underlayment</b> beneath does a lot of the waterproofing. Cracked or slipped tiles let more water reach it.",
       "<b>Flat roofs</b> (TPO, EPDM, modified bitumen and others) need to drain. Water that sits for days, called <b>ponding</b>, strains seams and the membrane."],
  faq=[("Why is my metal roof leaking?", "Often worn screw washers, loose screws, seams or flashing."),
       ("Can I walk on a tile roof?", "It's safer not to. Tiles crack underfoot. A roofer knows where to step."),
       ("How long should water sit on a flat roof?", "Many roofers say water still sitting a couple of days after rain is a problem."),
       ("Are metal roofs noisy in rain?", "They can be, depending on what's underneath. Attic insulation and decking help."),
       ("Can cracked tiles be replaced one at a time?", "Usually, yes, if matching tiles are available."),
       ("What's a flat roof membrane?", "The waterproof sheet on top of a flat roof, such as TPO, EPDM or modified bitumen.")]),
 "decide": dict(photo="tearoff", short="Repair or replace, roof life, door-to-door offers, buying a house.",
  h1="Roof decisions: repair or replace, hiring, and buying a house",
  lead="Big roof decisions are easier with the facts in front of you. Here's how to weigh repair against replacement, how to hire carefully, and what to check before buying a house.",
  how=["Most roof decisions come down to three things: the <b>age</b> of the roof, <b>how much</b> of it has problems, and whether the <b>deck</b> underneath is sound.",
       "A full replacement usually means a <b>tear-off</b> (removing old layers), checking and replacing bad decking, new underlayment, flashing and ventilation, then the new roof.",
       "The FTC's home repair advice applies to roofing: get the agreement in writing, check who you're hiring, and be wary of pressure and up-front payment demands."],
  faq=[("How do I know if I need a new roof or a repair?", "If problems are in one area and the roof isn't old, a repair often makes sense. Widespread wear, many leaks, or an old roof point to replacement."),
       ("What questions should I ask a roofer?", "What they found, what they recommend and why, what's included, how long it will take, whether a permit is needed, and to put it all in writing."),
       ("Can a new roof go over the old one?", "Sometimes local codes allow a second layer, but many roofers recommend a tear-off so the deck can be checked."),
       ("Do I need a permit for a new roof?", "Many cities and counties require one. Your roofer can tell you."),
       ("What should I check about the roof when buying a house?", "Its age, signs of leaks in the attic and ceilings, and a roofer's look if the inspection raises questions."),
       ("How do I avoid roofing scams?", "The FTC warns about door-to-door offers, high pressure, cash-only requests, and no written contract.")]),
}

