 ("drip-edge", "Drip edge", "Metal edging along the roof's edges that directs water away from the edge boards.", "storm"),
 ("pipe-boot", "Pipe boot", "A rubber or metal collar that seals around a plumbing vent pipe on the roof. A common leak spot as it ages.", "roof-leak-around-vent-pipe"),
 ("valley", "Valley", "The channel where two roof slopes meet. Lots of water flows through it.", "roof-leaks-only-in-heavy-rain"),
 ("ridge", "Ridge", "The top line where two roof slopes meet.", "storm"),
 ("hip", "Hip", "The sloped line where two roof planes meet on the outside corner of a hip roof.", "types"),
 ("ridge-vent", "Ridge vent", "A vent along the ridge that lets warm, moist attic air out.", "damp-attic"),
